import{a,_ as t}from"./chunks/mes-preview.6yKZZoVz.js";import{_ as r,o,c as i,a2 as l}from"./chunks/framework.CqGPl1zp.js";const s="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E7%A7%BB%E5%8A%A8%E7%AB%AF/%E5%B7%A5%E4%BD%9C%E5%8F%B0.png",d="/newx-doc/img/ad/zsxq_mes.png",n="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E5%9F%BA%E7%A1%80%E6%95%B0%E6%8D%AE%E8%A1%A8.png",m="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E7%94%9F%E4%BA%A7%E7%AE%A1%E7%90%86%E8%A1%A8.png",h="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E4%BB%93%E5%BA%93%E7%AE%A1%E7%90%86%E8%A1%A8.png",c="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E8%B4%A8%E9%87%8F%E7%AE%A1%E7%90%86%E8%A1%A8.png",u="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E8%AE%BE%E5%A4%87%E7%AE%A1%E7%90%86%E8%A1%A8.png",E="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E5%B7%A5%E5%85%B7%E7%AE%A1%E7%90%86%E8%A1%A8.png",p="/newx-doc/img/MES%E6%89%8B%E5%86%8C/%E5%8A%9F%E8%83%BD%E6%BC%94%E7%A4%BA/%E6%8E%92%E7%8F%AD%E7%AE%A1%E7%90%86%E8%A1%A8.png",k=JSON.parse('{"title":"MES 演示","description":"","frontmatter":{},"headers":[],"relativePath":"mes-preview.md","filePath":"mes-preview.md","lastUpdated":null}'),_={name:"mes-preview.md"};function g(f,e,A,b,B,q){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="mes-演示" tabindex="-1">MES 演示 <a class="header-anchor" href="#mes-演示" aria-label="Permalink to &quot;MES 演示&quot;">​</a></h1><h2 id="_1-演示地址" tabindex="-1">1. 演示地址 <a class="header-anchor" href="#_1-演示地址" aria-label="Permalink to &quot;1. 演示地址&quot;">​</a></h2><p>MES（Manufacturing Execution System，制造执行系统）用于连接生产计划与车间执行，围绕物料、工艺、生产工单和排产，串联领料、报工、入库、质量检验、设备维护与生产排班等制造现场业务。</p><h3 id="_1-1-mes-管理后台" tabindex="-1">1.1 MES 管理后台 <a class="header-anchor" href="#_1-1-mes-管理后台" aria-label="Permalink to &quot;1.1 MES 管理后台&quot;">​</a></h3><ul><li>演示地址：<a href="http://dashboard-vue3.yudao.iocoder.cn/" target="_blank" rel="noreferrer">http://dashboard-vue3.yudao.iocoder.cn/</a></li><li>菜单：&quot;MES 系统&quot;下的「基础数据」「生产管理」「仓库管理」「质量管理」「设备管理」「工具管理」「排班管理」</li><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-vue3</a> 的 <code>mes</code> 目录，基于 Vue3 + Element Plus 实现</li></ul><p><img src="'+a+'" alt="管理后台"></p><h3 id="_1-2-mes-后端" tabindex="-1">1.2 MES 后端 <a class="header-anchor" href="#_1-2-mes-后端" aria-label="Permalink to &quot;1.2 MES 后端&quot;">​</a></h3><p>支持 Spring Boot 单体、Spring Cloud 微服务架构</p><ul><li>单体仓库：<a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 的 <code>yudao-module-mes</code> 模块</li><li>微服务仓库：<a href="https://github.com/YunaiV/yudao-cloud" target="_blank" rel="noreferrer">https://github.com/YunaiV/yudao-cloud</a> 的 <code>yudao-module-mes</code> 服务</li></ul><h3 id="_1-3-mes-移动端" tabindex="-1">1.3 MES 移动端 <a class="header-anchor" href="#_1-3-mes-移动端" aria-label="Permalink to &quot;1.3 MES 移动端&quot;">​</a></h3><p>MES 提供 uni-app 移动端，基础数据、生产、仓储、质量和设备都可以在手机上处理，详见 <a href="./mes/mobile">《移动端 MES》</a>。</p><ul><li>仓库：<a href="https://github.com/yudaocode/yudao-ui-admin-uniapp" target="_blank" rel="noreferrer">https://github.com/yudaocode/yudao-ui-admin-uniapp</a> 的 <code>pages-mes</code> 目录</li></ul><p><img src="'+s+'" alt="移动端"></p><h2 id="_2-mes-启动" tabindex="-1">2. MES 启动 <a class="header-anchor" href="#_2-mes-启动" aria-label="Permalink to &quot;2. MES 启动&quot;">​</a></h2><p>参见 <a href="./mes/build">《MES 手册 —— 功能开启》</a> 文档，一般 3 分钟就可以启动完成。</p><h2 id="_3-mes-交流" tabindex="-1">3. MES 交流 <a class="header-anchor" href="#_3-mes-交流" aria-label="Permalink to &quot;3. MES 交流&quot;">​</a></h2><p>专属交流社区，欢迎扫码加入。</p><p><img src="'+d+'" alt="交流群"></p><h2 id="_4-功能描述" tabindex="-1">4. 功能描述 <a class="header-anchor" href="#_4-功能描述" aria-label="Permalink to &quot;4. 功能描述&quot;">​</a></h2><p>主要分为 7 个核心模块：基础数据、生产管理、仓库管理、质量管理、设备管理、工具管理、排班管理。</p><p><img src="'+t+'" alt="MES 功能列表"></p><h2 id="_5-表结构" tabindex="-1">5. 表结构 <a class="header-anchor" href="#_5-表结构" aria-label="Permalink to &quot;5. 表结构&quot;">​</a></h2><p>MES 共 <strong>133</strong> 张表，覆盖从基础数据到生产、仓储、质量的完整制造执行链路。各模块表前缀与规模汇总如下：</p><table tabindex="0"><thead><tr><th>模块</th><th>表前缀</th><th>表数量</th><th>核心职责</th></tr></thead><tbody><tr><td>基础数据</td><td><code>mes_md_</code></td><td>17</td><td>物料、客商、车间等主数据</td></tr><tr><td>生产管理</td><td><code>mes_pro_</code></td><td>17</td><td>工序 → 工艺 → 工单 → 排产 → 报工</td></tr><tr><td>仓库管理</td><td><code>mes_wm_</code></td><td>62</td><td>三级库位 + 库存事务驱动的全链路出入库</td></tr><tr><td>质量管理</td><td><code>mes_qc_</code></td><td>16</td><td>IQC / IPQC / OQC / RQC 四类质检闭环</td></tr><tr><td>设备管理</td><td><code>mes_dv_</code></td><td>12</td><td>设备台账、点检保养、维修工单</td></tr><tr><td>工具管理</td><td><code>mes_tm_</code></td><td>2</td><td>工装夹具台账与库存跟踪</td></tr><tr><td>排班管理</td><td><code>mes_cal_</code></td><td>7</td><td>班组 → 排班计划 → 排班日历</td></tr></tbody></table><h3 id="_5-1-基础数据" tabindex="-1">5.1 基础数据 <a class="header-anchor" href="#_5-1-基础数据" aria-label="Permalink to &quot;5.1 基础数据&quot;">​</a></h3><p>为生产、仓储、质量等业务提供主数据支撑，包括物料产品（分类、计量单位）、客户/供应商、车间/工作站、编码规则等。这些基础数据也可根据工厂实际情况，通过接口从 ERP 或其他外部系统同步。</p><p><img src="'+n+'" alt="基础数据表"></p><ul><li><a href="./mes/md/product">《【基础】物料产品、分类、计量单位》</a></li><li><a href="./mes/md/client-vendor">《【基础】客户管理、供应商管理》</a></li><li><a href="./mes/md/workshop">《【基础】车间设置、工作站设置》</a></li><li><a href="./mes/md/autocode">《【基础】编码规则》</a></li></ul><h3 id="_5-2-生产管理" tabindex="-1">5.2 生产管理 <a class="header-anchor" href="#_5-2-生产管理" aria-label="Permalink to &quot;5.2 生产管理&quot;">​</a></h3><p>围绕「<strong>工序 → 工艺流程 → 生产工单 → 排产 → 报工</strong>」主线，实现从计划到执行的闭环：</p><ul><li><strong>工序</strong>：最小可分辨加工步骤，定义物料输入与产出。</li><li><strong>工艺流程</strong>：将多道工序编排为完整加工路线，关联产品与工序级 BOM。</li><li><strong>生产工单</strong>：车间执行指令，来源可以是客户订单或库存备货；保存后自动计算物料需求，若产成品依赖多个半成品，可逐层生成子工单直至原材料级别。</li></ul><p><img src="'+m+'" alt="生产管理表"></p><ul><li><a href="./mes/pro/process-route">《【生产】工序设置、工艺流程》</a></li><li><a href="./mes/pro/work-order">《【生产】生产工单》</a></li><li><a href="./mes/pro/schedule-card">《【生产】生产排产、工序流转卡》</a></li><li><a href="./mes/pro/feedback">《【生产】生产报工》</a></li><li><a href="./mes/pro/andon">《【生产】安灯配置、安灯呼叫》</a></li></ul><h3 id="_5-3-仓库管理" tabindex="-1">5.3 仓库管理 <a class="header-anchor" href="#_5-3-仓库管理" aria-label="Permalink to &quot;5.3 仓库管理&quot;">​</a></h3><p>构建 <code>仓库 → 库区 → 库位</code> 三级空间结构，通过<strong>库存事务引擎</strong>统一驱动所有出入库单据的库存增减。所有单据均采用「起草 → 执行」两阶段流程，系统内置虚拟线边库管理在制物资。主要业务包括：</p><ul><li><strong>基础设施</strong>：仓库/库区/库位设置、条码赋码、SN 码管理、批次管理。</li><li><strong>库存核心</strong>：库存现有量（按物料+仓库+库区+库位+批次五维聚合）、库存事务流水。</li><li><strong>采购收货</strong>：到货通知 → IQC（可选）→ 采购入库 → 供应商退货。</li><li><strong>生产物流</strong>：生产领料、生产退料、物料消耗（报工自动扣减）、产品产出、产品入库。</li><li><strong>销售发货</strong>：发货通知 → 销售出库 → 销售退货。</li><li><strong>其他业务</strong>：外协发料/入库、杂项出入库、转移调拨、装箱管理、库存盘点。</li></ul><p><img src="'+h+'" alt="仓库管理表"></p><ul><li><a href="./mes/wm/warehouse-setup">《【仓库】仓库与库区库位、条码赋码、SN码》</a></li><li><a href="./mes/wm/stock">《【仓库】批次管理、库存现有量、库存事务》</a></li><li><a href="./mes/wm/purchase-in">《【仓库】到货通知、采购入库、采购退货》</a></li><li><a href="./mes/wm/issue-return">《【仓库】生产领料、生产退料、物料消耗》</a></li><li><a href="./mes/wm/product-in">《【仓库】产品产出、产品入库》</a></li><li><a href="./mes/wm/sales-out">《【仓库】发货通知、销售出库、销售退货》</a></li><li><a href="./mes/wm/outsource">《【仓库】外协发料、外协入库》</a></li><li><a href="./mes/wm/misc">《【仓库】其他入库、其他出库》</a></li><li><a href="./mes/wm/transfer">《【仓库】转移调拨、装箱管理》</a></li><li><a href="./mes/wm/stocktaking">《【仓库】库存盘点》</a></li></ul><h3 id="_5-4-质量管理" tabindex="-1">5.4 质量管理 <a class="header-anchor" href="#_5-4-质量管理" aria-label="Permalink to &quot;5.4 质量管理&quot;">​</a></h3><p>覆盖 <strong>IQC</strong>（来料）、<strong>IPQC</strong>（过程）、<strong>OQC</strong>（出货）、<strong>RQC</strong>（退货）四类质检场景，通过「检测项 → 质检方案 → 质检单」三层结构实现模板自动匹配、检验行自动生成、缺陷自动汇总，质检完成后回写来源单据。</p><p><img src="'+c+'" alt="质量管理表"></p><ul><li><a href="./mes/qc/base">《【质量】检测项设置、常见缺陷》</a></li><li><a href="./mes/qc/template">《【质量】质检方案》</a></li><li><a href="./mes/qc/iqc">《【质量】来料检验（IQC）》</a></li><li><a href="./mes/qc/ipqc">《【质量】过程检验（IPQC）》</a></li><li><a href="./mes/qc/oqc">《【质量】出货检验（OQC）》</a></li><li><a href="./mes/qc/rqc">《【质量】退货检验（RQC）》</a></li><li><a href="./mes/qc/pending-inspect">《【质量】待检任务、检验结果、缺陷记录》</a></li></ul><h3 id="_5-5-设备管理" tabindex="-1">5.5 设备管理 <a class="header-anchor" href="#_5-5-设备管理" aria-label="Permalink to &quot;5.5 设备管理&quot;">​</a></h3><p>覆盖设备全生命周期：<strong>设备台账</strong>（分类 + 基础信息）→ <strong>点检保养</strong>（项目 → 方案 → 执行记录）→ <strong>维修工单</strong>（报修 → 维修 → 验收）。</p><p><img src="'+u+'" alt="设备管理表"></p><ul><li><a href="./mes/dv/device">《【设备】设备类型、设备台账》</a></li><li><a href="./mes/dv/check-plan">《【设备】点检保养项目、点检保养方案》</a></li><li><a href="./mes/dv/check-record">《【设备】点检记录、保养记录、维修单》</a></li></ul><h3 id="_5-6-工具管理" tabindex="-1">5.6 工具管理 <a class="header-anchor" href="#_5-6-工具管理" aria-label="Permalink to &quot;5.6 工具管理&quot;">​</a></h3><p>管理生产过程中的工装夹具（模具、治具、刀具等），跟踪库存数量、可用数量与保养周期。</p><p><img src="'+E+'" alt="工具管理表"></p><ul><li><a href="./mes/tm/tool">《【工具】工具类型、工装夹具台账》</a></li></ul><h3 id="_5-7-排班管理" tabindex="-1">5.7 排班管理 <a class="header-anchor" href="#_5-7-排班管理" aria-label="Permalink to &quot;5.7 排班管理&quot;">​</a></h3><p>通过「班组 → 排班计划 → 排班日历」三层结构，支持单白班、两班倒、三班倒等轮班模式，计划确认后自动生成逐日排班日历。</p><p><img src="'+p+'" alt="排班管理表"></p><ul><li><a href="./mes/cal/team">《【排班】班组设置、节假日设置》</a></li><li><a href="./mes/cal/calendar">《【排班】排班计划、排班日历》</a></li></ul>',54)])])}const x=r(_,[["render",g]]);export{k as __pageData,x as default};
